import{_ as a,o as t,c as n,a2 as i}from"./chunks/framework.D66Xq0Kv.js";const h=JSON.parse('{"title":"8. Control Flow and Structural Iteration","description":"","frontmatter":{},"headers":[],"relativePath":"spec/08-control-flow.md","filePath":"spec/08-control-flow.md","lastUpdated":null}'),o={name:"spec/08-control-flow.md"};function r(s,e,l,c,p,d){return t(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="_8-control-flow-and-structural-iteration" tabindex="-1">8. Control Flow and Structural Iteration <a class="header-anchor" href="#_8-control-flow-and-structural-iteration" aria-label="Permalink to &quot;8. Control Flow and Structural Iteration&quot;">​</a></h1><h2 id="_8-1-runtime-if" tabindex="-1">8.1 Runtime <code>if</code> <a class="header-anchor" href="#_8-1-runtime-if" aria-label="Permalink to &quot;8.1 Runtime \`if\`&quot;">​</a></h2><p><code>if</code> is an expression over a scalar <code>bool</code>. Both branches must have identical result types.</p><p>It may lower to backend control flow or selection depending on the backend and context.</p><h2 id="_8-2-static-for" tabindex="-1">8.2 <code>static for</code> <a class="header-anchor" href="#_8-2-static-for" aria-label="Permalink to &quot;8.2 \`static for\`&quot;">​</a></h2><p><code>static for</code> performs compile-time structural expansion:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>var x = embedding.forward(tokens)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>static for layer in layers {</span></span>
<span class="line"><span>    x = layer.forward(x)</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>The iterable MUST be a statically known structural collection such as:</p><ul><li>a sub-block array;</li><li>a compile-time integer range;</li><li>another future compile-time collection.</li></ul><p>The loop MUST NOT depend on runtime tensor values.</p><h2 id="_8-3-static-integer-ranges" tabindex="-1">8.3 Static integer ranges <a class="header-anchor" href="#_8-3-static-integer-ranges" aria-label="Permalink to &quot;8.3 Static integer ranges&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>static for i in 0..Steps {</span></span>
<span class="line"><span>    ...</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><code>start..stop</code> iterates over the compile-time integers <code>start &lt;= i &lt; stop</code>; both bounds MUST be compile-time integers (literals, generic dimensions, or arithmetic on them). The body is expanded at compile time exactly as the array form is. The loop variable is an <code>i64</code> scalar value holding the position of each iteration: it may be cast, compared, or used in arithmetic like any scalar, but it is not a compile-time integer, so it cannot index a sub array or appear in a shape — iterate the array itself for that.</p><h2 id="_8-4-runtime-loops" tabindex="-1">8.4 Runtime loops <a class="header-anchor" href="#_8-4-runtime-loops" aria-label="Permalink to &quot;8.4 Runtime loops&quot;">​</a></h2><p><code>while</code> is reserved for future runtime control flow and MUST NOT be accepted as a user identifier.</p><p>Runtime loops require explicit rules for state threading, shape invariance, termination-independent graph semantics, and backend export. They are intentionally excluded from the first implementation.</p><h2 id="_8-5-recursion" tabindex="-1">8.5 Recursion <a class="header-anchor" href="#_8-5-recursion" aria-label="Permalink to &quot;8.5 Recursion&quot;">​</a></h2><p>Function, op, and block-method recursion is forbidden in the initial language version.</p><p>Future recursion support, if any, MUST be explicit in the language specification rather than accidentally inherited from backend behavior.</p>`,19)])])}const m=a(o,[["render",r]]);export{h as __pageData,m as default};
